## solutions

#### recursive

```cpp
#include <vector>
#include <string>
#include <tuple>

std::tuple<std::string, int> parseGroup(std::string str, int pos) {
  if (str[pos] == '(') {
    int closePos = str.find(')', pos);
    std::string chars = str.substr(pos + 1, closePos - pos - 1);
    return std::tuple { chars, closePos + 1 };
  } else {
    return std::tuple { std::string(1, str[pos]), pos + 1 };
  }
} 

std::vector<std::string> parentheticalPossibilities(std::string str, int pos) {
  if (pos == str.length()) {
    return std::vector<std::string> { "" };
  }

  auto [ chars, nextPos ] = parseGroup(str, pos);
  std::vector<std::string> suffixes = parentheticalPossibilities(str, nextPos);

  std::vector<std::string> result;
  for (std::string suffix : suffixes) {
    for (char ch : chars) {
      result.push_back(ch + suffix);
    }
  }

  return result;
}

std::vector<std::string> parentheticalPossibilities(std::string str) {
  return parentheticalPossibilities(str, 0);
}
```

- n = length of the string, m = length of largest parenthetical group
- Time: ~O(m^n)
- Space: ~O(m^n)
